function SkillIcon({ name }: { name: string }) {
  const path = brandPaths[skillBrands[name]];
  if (path) return <svg role="img" aria-label={`${name} icon`} viewBox="0 0 24 24" className="h-6 w-6 shrink-0 fill-current text-primary transition-transform duration-300 group-hover/skill:scale-110"><path d={path} /></svg>;
  const Symbol = skillSymbols[name] ?? Code2;
  return <Symbol aria-hidden="true" className="h-6 w-6 shrink-0 text-primary transition-transform duration-300 group-hover/skill:scale-110" />;
}

